const h = params.size;
const r = h * 0.28;
const c = params.color;
const pale = api.mix(c, '#ffffff', 0.52);
const deep = api.mix(c, '#402070', 0.32);
const glow = api.mix(c, '#ffffff', 0.18);
const bellBottom = h * 0.70;
const bellProfile = [
  [0, h],
  [r * 0.22, h * 0.985],
  [r * 0.48, h * 0.94],
  [r * 0.72, h * 0.88],
  [r * 0.90, h * 0.80],
  [r, h * 0.735],
  [r * 0.96, h * 0.69],
  [r * 0.78, h * 0.675],
  [r * 0.55, h * 0.705],
  [r * 0.30, h * 0.735],
  [0, h * 0.745]
];
const bell = api.lathe(bellProfile, 28);
bell.vertexColor((x, y, z) => {
  const edge = Math.min(1, Math.sqrt(x * x + z * z) / r);
  const shimmer = 0.10 * api.noise3(x * 4 / h, y * 5 / h, z * 4 / h);
  return api.mix(pale, c, Math.max(0, Math.min(1, edge * 0.55 + shimmer)));
});
api.add(bell, { preset: 'glass', color: c, roughness: 0.12, opacity: 0.68, emissive: c, emissiveIntensity: 1.25, vertexColors: true });
const rimMat = { preset: 'emissive', color: pale, emissive: c, emissiveIntensity: 2.8, opacity: 0.82, roughness: 0.2 };
api.add(api.torus(r * 0.94, r * 0.045).rotate(90, 0, 0).translate(0, h * 0.695, 0), rimMat);
const coreProfile = [[0, h * 0.70], [r * 0.20, h * 0.715], [r * 0.28, h * 0.78], [r * 0.20, h * 0.87], [0, h * 0.91]];
api.add(api.lathe(coreProfile, 18), { preset: 'emissive', color: glow, emissive: glow, emissiveIntensity: 2.2, opacity: 0.48, roughness: 0.25 });
const nodeMat = { preset: 'emissive', color: deep, emissive: c, emissiveIntensity: 1.6, opacity: 0.72, roughness: 0.3 };
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI * 2 / 8;
  const rr = r * 0.49;
  api.add(api.sphere(r * 0.075, 1).scale(1, 0.65, 1).translate(Math.cos(a) * rr, h * 0.72, Math.sin(a) * rr), nodeMat);
}
const tentacleMat = { preset: 'glass', color: c, emissive: c, emissiveIntensity: 1.55, opacity: 0.72, roughness: 0.22 };
for (let i = 0; i < 12; i++) {
  const a = i * Math.PI * 2 / 12;
  const ring = i % 2 === 0 ? r * 0.68 : r * 0.48;
  const len = h * (0.50 + 0.12 * api.rng());
  const top = bellBottom + h * 0.012;
  const pts = [];
  const phase = api.rng() * Math.PI * 2;
  const sway = r * (0.10 + api.rng() * 0.08);
  for (let j = 0; j <= 11; j++) {
    const t = j / 11;
    const y = top - len * t;
    const wave = Math.sin(t * Math.PI * (2.4 + (i % 3) * 0.35) + phase) * sway * (0.25 + t * 0.75);
    const twist = Math.cos(t * Math.PI * 2 + phase) * sway * 0.45 * t;
    pts.push([Math.cos(a) * ring + Math.cos(a) * wave - Math.sin(a) * twist, y, Math.sin(a) * ring + Math.sin(a) * wave + Math.cos(a) * twist]);
  }
  api.add(api.tube(pts, r * (i % 2 === 0 ? 0.026 : 0.019), 6), tentacleMat);
}
const armMat = { preset: 'glass', color: pale, emissive: c, emissiveIntensity: 2.0, opacity: 0.78, roughness: 0.2 };
for (let i = 0; i < 4; i++) {
  const a = i * Math.PI * 0.5 + Math.PI * 0.25;
  const pts = [];
  const armTop = h * 0.75;
  const len = h * (0.45 + 0.035 * i);
  for (let j = 0; j <= 12; j++) {
    const t = j / 12;
    const radial = r * (0.18 + 0.12 * t);
    const curl = Math.sin(t * Math.PI * 3.2 + i * 1.3) * r * 0.10 * t;
    pts.push([Math.cos(a) * radial - Math.sin(a) * curl, armTop - len * t, Math.sin(a) * radial + Math.cos(a) * curl]);
  }
  api.add(api.tube(pts, r * 0.047, 7), armMat);
}
api.collider({ kind: 'sphere', radius: r * 0.88, offset: [0, h * 0.82, 0] });
api.collider({ kind: 'cylinder', radius: r * 0.45, halfHeight: h * 0.25, offset: [0, h * 0.46, 0] });
return api.build();
